import {heights,surfaces,configurations} from './workshop-core.mjs';
import {missions,pages,modelNotice,configLabel,designMessages,predictionChoices,claimChoices} from './fair-test-content.mjs';
import {fairView,startFair,setFairPlan,setFairPage,setFairPrediction,setFairClaim,setFairNote,addFairSupport,revealFair,selectFairTrial,resumeFair,keepFair,designFor,evidenceFor} from './fair-test-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const help='Change one factor to explore its effect. Keep the same cart, no added push, and measure from the ramp foot. A stopping distance is an observation. An idea about why it stopped there is an explanation. You can ask a grown-up to think with you.';
const mission=i=>missions.find(m=>m.id===i.mission);
const config=id=>configurations.find(c=>c.id===id);
function ramp(i,side){
 const c=config(i[side.toLowerCase()]),top={low:95,middle:68,high:40}[c.height];
 const selected=i.selected?.side===side?i.trials.find(t=>t.side===side&&t.index===i.selected.index):null;
 const x=selected?130+selected.distance*5:62,y=selected?124:top-10;
 const text=`Setup ${side}: ${configLabel(c.id)}.${selected?` Trial ${selected.index}: ${selected.distance} model cm.`:' Cart waits at the top.'}`;
 return `<figure class="fair-ramp"><svg viewBox="0 0 300 160" role="img" aria-label="${esc(text)}"><path d="M22 136H288" stroke="#183f39" stroke-width="2"/><path d="M35 136V${top}H62L130 136Z" fill="#d6b77d" stroke="#75593c" stroke-width="2"/><path d="M62 ${top}L130 136" stroke="#183f39" stroke-width="3"/><rect x="130" y="136" width="150" height="9" fill="${c.surface==='rough'?'#d6b77d':'#abc4da'}"/>${c.surface==='rough'?Array.from({length:15},(_,n)=>`<path d="M${132+n*10} 142l3-4 3 4" stroke="#75593c" fill="none"/>`).join(''):''}<path d="M130 125v28" stroke="#183f39"/><g transform="translate(${x},${y})"><rect x="-13" y="-12" width="26" height="15" rx="2" fill="${side==='A'?'#397958':'#9a6526'}"/><rect x="-8" y="-24" width="16" height="12" fill="#e9b84a" stroke="#183f39"/><circle cx="-8" cy="5" r="4" fill="#183f39"/><circle cx="8" cy="5" r="4" fill="#183f39"/></g><text x="15" y="24" font-size="20" font-weight="bold" fill="#183f39">${side}</text><text x="133" y="157" font-size="10" fill="#183f39">0 · ramp foot</text></svg><figcaption>${esc(text)}</figcaption></figure>`;
}
function choices(list,value,kind){return `<div class="fair-choices" role="group" aria-label="${kind==='prediction'?'Which setup might go farther?':'Your provisional claim'}">${list.map(x=>btn(`data-fair-${kind}="${esc(x.id)}" aria-pressed="${x.id===value}"`,x.label,x.id===value)).join('')}${btn(`data-fair-${kind}="clear" aria-pressed="${value===null}"`,'Leave blank',value===null)}</div>`;}
function designText(i){const d=designFor(i).code;return typeof designMessages[d]==='string'?designMessages[d]:designMessages[d]?.[i.mission]||'';}
function evidenceText(i){
 const e=evidenceFor(i),values=side=>i.trials.filter(t=>t.side===side).sort((a,b)=>a.index-b.index).map(t=>t.distance).join(', ')||'not tried';
 let message=e.status==='missing'?'Evidence for a comparison is missing. Try both setups.':e.status==='unbalanced'?'The sides have different numbers of trials. Try matching repeats.':e.status==='A'?'In these shown model trials, every A distance was larger than every B distance.':e.status==='B'?'In these shown model trials, every B distance was larger than every A distance.':'The shown ranges overlap or touch. That does not establish that the setups are equal.';
 return `<p><strong>Shown distances:</strong> A: ${values('A')}; B: ${values('B')} model cm.</p><p>${message}</p>${['A','B'].map(s=>e.counts[s]===3?`<p class="tiny">${s}: ${e.ranges[s].min}–${e.ranges[s].max} model cm. These three shown repeats ${e.variation[s]?'differed':'were the same'}.</p>`:'').join('')}<p class="fair-design">${esc(designText(i))}</p>`;
}
function plan(i){return `<h2 tabindex="-1" id="fair-prompt">What shall we compare?</h2><label for="fair-mission">Our question</label><select id="fair-mission" data-fair-plan="mission">${missions.map(m=>`<option value="${m.id}"${i.mission===m.id?' selected':''}>${esc(m.title)}</option>`).join('')}</select><div class="fair-setups">${['A','B'].map(side=>{const c=config(i[side.toLowerCase()]);return `<fieldset><legend>Setup ${side}</legend>${ramp(i,side)}${[['height',heights],['surface',surfaces]].map(([factor,options])=>`<label for="fair-${side}-${factor}">${factor==='height'?'Ramp height':'Landing surface'}</label><select id="fair-${side}-${factor}" data-fair-side="${side}" data-fair-factor="${factor}">${options.map(o=>`<option value="${o.id}"${c[factor]===o.id?' selected':''}>${esc(o.label)}</option>`).join('')}</select>`).join('')}</fieldset>`;}).join('')}</div><p class="fair-design"><strong>Comparison check:</strong> ${esc(designText(i))}</p><p class="tiny">Same cart. No added push. Measure horizontally from the ramp foot. ${i.trials.length?'Editing a setup or question keeps these trials and begins a new investigation.':'After a result appears, editing a setup or question keeps that work and begins a new investigation.'}</p>${btn('data-fair-page="try"','Try the setups',true)}`;}
function ruler(i){return `<figure class="fair-ruler"><svg viewBox="0 0 640 150" role="img" aria-label="All revealed distances on one zero to thirty model centimetre ruler. Exact distances are in the table."><path d="M40 115H610" stroke="#183f39" stroke-width="2"/>${Array.from({length:31},(_,n)=>`<path d="M${40+n*19} 115v${n%5===0?12:6}" stroke="#183f39"/>${n%5===0?`<text x="${40+n*19}" y="145" text-anchor="middle" font-size="15">${n}</text>`:''}`).join('')}${['A','B'].map((s,k)=>`<text x="8" y="${35+k*44}" font-size="20" font-weight="bold">${s}</text>${i.trials.filter(t=>t.side===s).map(t=>`<g><circle cx="${40+t.distance*19}" cy="${18+k*44+t.index*8}" r="7" fill="${s==='A'?'#397958':'#9a6526'}"/><text x="${40+t.distance*19+10}" y="${23+k*44+t.index*8}" font-size="12">${t.index}</text></g>`).join('')}`).join('')}</svg><figcaption>Distance from the ramp foot · model cm. Small numbers identify each trial.</figcaption></figure>`;}
function trialTable(i){return `<table class="fair-table"><caption>Three examples in this model</caption><thead><tr><th scope="col">Trial</th><th scope="col">A · model cm</th><th scope="col">B · model cm</th></tr></thead><tbody>${[1,2,3].map(n=>`<tr><th scope="row">${n}</th>${['A','B'].map(side=>{const t=i.trials.find(t=>t.side===side&&t.index===n);return `<td>${t?`<button type="button" class="text-button" data-fair-replay="${side}" data-index="${n}" aria-pressed="${i.selected?.side===side&&i.selected.index===n}">${t.distance}<span class="sr-only"> · show ${side} trial ${n} again</span></button>`:'not tried'}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function tryPage(i){return `<h2 tabindex="-1" id="fair-prompt">Which setup might go farther?</h2>${choices(predictionChoices,i.prediction,'prediction')}${i.prediction?`<p class="tiny">Unscored prediction${i.predictionAfterResults?' selected after a result was shown':''}.</p>`:''}<div class="fair-setups fair-apparatus">${ramp(i,'A')}${ramp(i,'B')}</div><div class="fair-releases">${['A','B'].map(side=>{const rows=i.trials.filter(t=>t.side===side),n=rows.length,next=[1,2,3].find(index=>!rows.some(t=>t.index===index));return `<div>${btn(`data-fair-reveal="${side}"${n===3?' disabled':''}`,n===3?`${side}: all three shown`:`Show ${side} trial ${next}`,n<3)}<span>${n} of 3 shown ${'●'.repeat(n)}${'○'.repeat(3-n)}</span></div>`;}).join('')}</div>${ruler(i)}${trialTable(i)}<div class="fair-evidence">${evidenceText(i)}</div><p class="tiny">Selecting a table result shows it again; it adds no trial. Three examples here do not establish how many trials a real investigation needs.</p>${btn('data-fair-page="tell"','Tell the crew')}`;}
function tell(i){return `<h2 tabindex="-1" id="fair-prompt">What would you tell the crew?</h2><p>Choose a provisional claim, leave it blank, or talk with a grown-up.</p>${choices(claimChoices,i.claim,'claim')}<div class="fair-evidence">${evidenceText(i)}</div><label for="fair-note">Your own words (optional)</label><textarea id="fair-note" maxlength="800" rows="3" aria-describedby="fair-note-help"></textarea><p id="fair-note-help" class="tiny">Up to 800 characters. Your words are kept exactly and are not graded.</p><div class="fair-choices">${btn('data-fair-keep',i.kept?'Investigation kept':'Keep this investigation',true)}${btn('data-fair-page="try"','Collect more results')}</div><p class="tiny">Keeping is a bookmark. Unfinished investigations can be kept too.</p>`;}
const historyLabel=i=>`Investigation ${i.id}${i.kept?' · kept':''}: ${configLabel(i.a)} / ${configLabel(i.b)}`;
function history(v){return `<details class="fair-history"><summary>Our investigations (${v.investigations.length} of 12)</summary><p>Up to 12 readable investigations stay here. Starting another at the limit removes the oldest readable one. Earlier unsupported work stays in place.</p>${[...v.investigations].reverse().map(i=>`<p>${btn(`data-fair-resume="${i.id}"`,historyLabel(i))}</p>`).join('')}</details>${v.earlier.length?`<details><summary>Earlier work (${v.earlier.length})</summary><p>This saved work cannot be continued here. Its original content is retained.</p>${v.earlier.map(x=>`<pre>${esc(JSON.stringify(x,null,2))}</pre>`).join('')}</details>`:''}`;}
export function fairTestPage(state){
 const v=fairView(state),i=v.current;
 const heading=`<header class="page-heading"><a class="back" href="#workshop">← Back to the Workshop</a><h1>Fair Test Bench</h1><p>Two ramps. One question. What can the comparison tell us?</p></header>`;
 if(v.status==='unavailable')return `<div class="fair-page">${heading}<section class="fair-sheet"><h2>Earlier work is safe</h2><p>This saved Fair Test Bench uses a format we cannot continue here. It has been left unchanged. The original Workshop is still open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.fairTests,null,2))}</pre></details></section></div>`;
 return `<div class="fair-page">${heading}<section class="fair-sheet">${!i?`<h2>Plan a delivery test</h2><p>Choose two ramp setups and explore three authored examples for each. This is practice, with no score.</p>${btn('data-fair-start','Start an investigation',true)}`:`<nav class="fair-tabs" aria-label="Investigation pages">${pages.map((p,n)=>btn(`data-fair-page="${p}" aria-current="${v.page===p?'step':'false'}"`,`${n+1}. ${p[0].toUpperCase()+p.slice(1)}`,v.page===p)).join('')}</nav><div class="fair-mission"><strong>${esc(mission(i)?.title)}</strong><p>${esc(mission(i)?.purpose)}</p><p class="tiny">A: ${esc(configLabel(i.a))} · B: ${esc(configLabel(i.b))}</p></div><p class="fair-notice">${esc(modelNotice)}</p><p class="fair-status" role="status" tabindex="-1" id="fair-status"></p>${v.page==='try'?tryPage(i):v.page==='tell'?tell(i):plan(i)}<details id="fair-help"><summary>Help us think</summary><p>${help}</p>${hearButton(help,'Hear this help')}${btn('data-fair-support="together" aria-pressed="'+i.support.includes('together')+'"','We thought together',i.support.includes('together'))}</details><div class="fair-new">${v.investigations.length>=12?'<p>All 12 spaces are used. “Start another” removes the oldest readable investigation.</p>':''}${btn('data-fair-start','Start another')}</div>`}</section>${history(v)}</div>`;
}
export function fairTestNotes(state){
 const v=fairView(state);if(v.status==='missing')return '';
 if(v.status==='unavailable')return `<details class="panel"><summary>Fair Test Bench · earlier format</summary><p>Original saved work is retained unchanged.</p><pre>${esc(JSON.stringify(state.fairTests,null,2))}</pre></details>`;
 return `<details class="panel"><summary>Fair Test Bench (${v.investigations.length} investigations)</summary><p>Practice with authored model examples. No physical testing competence or mastery is inferred. Support, familiarity, prediction and claims are separate reports. Full saved work is included in the download.</p>${v.investigations.map(i=>`<section><h3>Investigation ${i.id}${i.kept?' · kept':''}</h3><p>${esc(mission(i)?.title)} A: ${esc(configLabel(i.a))}. B: ${esc(configLabel(i.b))}.</p>${evidenceText(i)}<p>Prediction: ${esc(i.prediction||'blank')}${i.predictionAfterResults?' (after results)':''}. Claim: ${esc(i.claim||'blank')}. Support: ${esc(i.support.join(', ')||'none reported')}. Familiar: ${i.familiar?'yes':'no'}.</p><p class="fair-original">${esc(i.note)}</p></section>`).join('')}${v.earlier.length?`<details><summary>Earlier unreadable work</summary><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}</details>`;
}
export function bindFairTest(state,{save,render,focus}){
 const show=(message='',target='#fair-prompt')=>{save();render();const status=document.querySelector('#fair-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('[data-fair-start]',()=>{const full=fairView(state).investigations.length>=12;startFair(state);show(full?'A new investigation is ready. The oldest readable investigation was removed, as described.':'A new investigation is ready. Earlier trials stay in their investigations.');});
 bind('[data-fair-page]',b=>{setFairPage(state,b.dataset.fairPage);show();});
 bind('[data-fair-resume]',b=>{resumeFair(state,Number(b.dataset.fairResume));show();});
 const change=(key,value,target)=>{const result=setFairPlan(state,key,value);show(result==='forked'?'A new investigation is ready. Your prior trials are kept unchanged.':result==='capacity'?'All 12 spaces are used. Your plan and trials are unchanged. Use “Start another” to remove the oldest readable investigation before editing.':'',result==='capacity'?'#fair-status':target);};
 document.querySelector('[data-fair-plan]')?.addEventListener('change',e=>change('mission',e.target.value,'#fair-mission'));
 document.querySelectorAll('[data-fair-side]').forEach(s=>s.addEventListener('change',()=>{const side=s.dataset.fairSide,c=config(fairView(state).current[side.toLowerCase()]);change(side.toLowerCase(),`${s.dataset.fairFactor==='height'?s.value:c.height}-${s.dataset.fairFactor==='surface'?s.value:c.surface}`,`#${s.id}`);}));
 for(const [kind,setter]of [['prediction',setFairPrediction],['claim',setFairClaim]])bind(`[data-fair-${kind}]`,b=>{setter(state,b.dataset[`fair${kind[0].toUpperCase()+kind.slice(1)}`]==='clear'?null:b.dataset[`fair${kind[0].toUpperCase()+kind.slice(1)}`]);show('',`[data-fair-${kind}="${b.dataset[`fair${kind[0].toUpperCase()+kind.slice(1)}`]}"]`);});
 bind('[data-fair-reveal]',b=>{const t=revealFair(state,b.dataset.fairReveal);show(t?`${t.side} trial ${t.index}: ${t.distance} model cm.`:'All three examples are shown.','#fair-status');});
 bind('[data-fair-replay]',b=>{selectFairTrial(state,b.dataset.fairReplay,Number(b.dataset.index));show('Showing an existing trial. No result was added.','#fair-status');});
 bind('[data-fair-keep]',()=>{keepFair(state);show('Investigation kept. You can keep exploring.','#fair-status');});
 bind('[data-fair-support]',b=>{addFairSupport(state,b.dataset.fairSupport);save();b.setAttribute('aria-pressed','true');});
 const note=document.querySelector('#fair-note');if(note){note.value=fairView(state).current.note;note.addEventListener('input',()=>{setFairNote(state,note.value);const i=fairView(state).current,keep=document.querySelector('[data-fair-keep]'),entry=document.querySelector(`[data-fair-resume="${i.id}"]`);if(keep)keep.textContent=i.kept?'Investigation kept':'Keep this investigation';if(entry)entry.textContent=historyLabel(i);const status=document.querySelector('#fair-status');if(status)status.textContent='Your words changed. You can keep this version when you are ready.';save();});}
 const details=document.querySelector('#fair-help');details?.addEventListener('toggle',()=>{if(details.open){addFairSupport(state,'help');save();}});
 document.querySelectorAll('.fair-page [data-speak]').forEach(b=>b.addEventListener('click',()=>{addFairSupport(state,'audio');save();}));
}
